import java.util.ArrayList;

public class Main {
    public static void main(String[] args) {
        ArrayList<String> names = new ArrayList<>(); //~ An ArrayList grows as you add, unlike an array.
        names.add("Asha");
        names.add("Ravi");
        names.add(0, "Zoya"); //~ add(0, x) inserts at the front and shifts the rest right.
        names.remove("Ravi"); //~ remove by value.
        System.out.println(names + " " + names.size()); //~ Lists print nicely: [Zoya, Asha].
    }
}

import java.util.HashSet;

public class Main {
    public static void main(String[] args) {
        HashSet<Integer> seen = new HashSet<>();
        int[] nums = {3, 1, 3, 2, 1};
        for (int x : nums) seen.add(x);
        System.out.println(seen.size());
    }
}

